  "description": "עמותה שהקימה רשת ארצית של מטפלים ותיקים בטראומת מלחמה, שנותנים טיפול פסיכולוגי בקליניקות פרטיות במחיר מסובסד, לילדים, למבוגרים ולמשפחות. הדגש הוא על 'המעגל השני' של נפגעי המלחמה, שלרוב לא זכאים לטיפול מהמדינה: בני משפחה מורחבת של לוחמים, מי שאדם קרוב אליו נפצע, נחטף או נהרג, והורים וילדים במצוקה. אפשר לקבל טיפול ארוך טווח (עד שנה).",
